local SandMoldMaker = {}
local PRODUCTS = {
    iron_sand_mold = { name = "Železni peskan model", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 170, prestige = 3, happiness = 2, description = "Železni peskan model za livarstvo." },
    bronze_sand_mold = { name = "Bronast peskan model", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 415, prestige = 5, happiness = 3, description = "Bronast peskan model za natančne ulitke." },
    silver_sand_mold = { name = "Srebrni peskan model", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 1000, prestige = 10, happiness = 4, description = "Srebrni peskan model za plemiške livarje." },
    gilded_sand_mold = { name = "Pozlačeni peskan model", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 2150, prestige = 19, happiness = 5, description = "Pozlačeni peskan model za dvorne livarje." },
    jewel_set_sand_mold = { name = "Draguljasti peskan model", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4650, prestige = 35, happiness = 7, description = "Draguljasti peskan model za kraljevske livarje." },
    royal_sovereign_sand_mold = { name = "Kraljevski suvereni peskan model", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 10000, prestige = 67, happiness = 13, description = "Suvereni peskan model z biseri za krono." },
}
local BUILDINGS = {
    sandmold_workshop = { name = "Peskana delavnica", cost = { gold = 345, wood = 180, stone = 135, iron = 8 }, upkeep = 6, qualityBonus = 5 },
    sandmold_house = { name = "Peskana hiša", cost = { gold = 1230, wood = 360, stone = 275, silver = 7, iron = 7 }, upkeep = 26, qualityBonus = 18 },
    master_sandmold_atelier = { name = "Mojstrski peskani atelje", cost = { gold = 3080, wood = 420, stone = 525, silver = 36, gold = 7 }, upkeep = 72, qualityBonus = 30 },
    sovereign_sandmold_palace = { name = "Suverena peskana palača", cost = { gold = 13150, wood = 645, stone = 835, gold = 84, jewel = 19 }, upkeep = 258, qualityBonus = 55, prestigeBonus = 50 },
}
SandMoldMaker.ironStock = 14; SandMoldMaker.bronzeStock = 12; SandMoldMaker.woodStock = 16; SandMoldMaker.leatherStock = 10; SandMoldMaker.silverStock = 8; SandMoldMaker.goldStock = 6; SandMoldMaker.jewelStock = 4; SandMoldMaker.pearlStock = 4
SandMoldMaker.productStock = {}; SandMoldMaker.buildings = {}; SandMoldMaker.maker = nil; SandMoldMaker.activeMaking = {}; SandMoldMaker.totalProducts = 0; SandMoldMaker.dayTimer = 0
function SandMoldMaker.init() SandMoldMaker.ironStock=14; SandMoldMaker.bronzeStock=12; SandMoldMaker.woodStock=16; SandMoldMaker.leatherStock=10; SandMoldMaker.silverStock=8; SandMoldMaker.goldStock=6; SandMoldMaker.jewelStock=4; SandMoldMaker.pearlStock=4; SandMoldMaker.productStock={}; SandMoldMaker.buildings={}; SandMoldMaker.maker=nil; SandMoldMaker.activeMaking={}; SandMoldMaker.totalProducts=0; SandMoldMaker.dayTimer=0; print("[SandMoldMaker] Royal Sand Mold Maker System initialized (6 products, 4 buildings)") end
function SandMoldMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SandMoldMaker.maker={name=n or ("Peskar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Peskar najet: %s (spretnost: %d)",SandMoldMaker.maker.name,s),"success") end; return true end
function SandMoldMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SandMoldMaker.build(id) local ok,e=SandMoldMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SandMoldMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SandMoldMaker.getQualityBonus() local b=0; for _,bd in ipairs(SandMoldMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SandMoldMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and SandMoldMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and SandMoldMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and SandMoldMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and SandMoldMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and SandMoldMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SandMoldMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SandMoldMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SandMoldMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SandMoldMaker.buildings==0 then return false,"Potrebna peskana delavnica" end; if not SandMoldMaker.maker then return false,"Potreben peskar" end; return true end
function SandMoldMaker.make(pt,qty) qty=qty or 1; local ok,e=SandMoldMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then SandMoldMaker.ironStock=SandMoldMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then SandMoldMaker.bronzeStock=SandMoldMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then SandMoldMaker.woodStock=SandMoldMaker.woodStock-d.woodCost*qty end; if d.leatherCost then SandMoldMaker.leatherStock=SandMoldMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then SandMoldMaker.silverStock=SandMoldMaker.silverStock-d.silverCost*qty end; if d.goldCost then SandMoldMaker.goldStock=SandMoldMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SandMoldMaker.jewelStock=SandMoldMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then SandMoldMaker.pearlStock=SandMoldMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if SandMoldMaker.maker then t=math.max(1,t-math.floor(SandMoldMaker.maker.skill/13)) end; table.insert(SandMoldMaker.activeMaking,{id="sandmold_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SandMoldMaker.completeMaking(m) local q=1.0+(SandMoldMaker.getQualityBonus()/100); if SandMoldMaker.maker then q=q+(SandMoldMaker.maker.skill/140) end; q=math.min(2.5,q); SandMoldMaker.productStock[m.productType]=(SandMoldMaker.productStock[m.productType] or 0)+m.quantity; SandMoldMaker.totalProducts=SandMoldMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SandMoldMaker.maker then SandMoldMaker.maker.itemsMade=SandMoldMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then SandMoldMaker.maker.skill=math.min(100,SandMoldMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Peskan model izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"sandmold.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function SandMoldMaker.update(dt) if not _G.state then return end; SandMoldMaker.dayTimer=SandMoldMaker.dayTimer+dt; if SandMoldMaker.dayTimer>=30 then SandMoldMaker.dayTimer=0; for i=#SandMoldMaker.activeMaking,1,-1 do local m=SandMoldMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SandMoldMaker.completeMaking(m); table.remove(SandMoldMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SandMoldMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SandMoldMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SandMoldMaker.getStats() return {ironStock=SandMoldMaker.ironStock,bronzeStock=SandMoldMaker.bronzeStock,woodStock=SandMoldMaker.woodStock,leatherStock=SandMoldMaker.leatherStock,silverStock=SandMoldMaker.silverStock,goldStock=SandMoldMaker.goldStock,jewelStock=SandMoldMaker.jewelStock,pearlStock=SandMoldMaker.pearlStock,productStock=SandMoldMaker.productStock,numBuildings=#SandMoldMaker.buildings,hasMaker=SandMoldMaker.maker~=nil,makerName=SandMoldMaker.maker and SandMoldMaker.maker.name or "—",makerSkill=SandMoldMaker.maker and SandMoldMaker.maker.skill or 0,activeMaking=#SandMoldMaker.activeMaking,totalProducts=SandMoldMaker.totalProducts} end
return SandMoldMaker
